import h5py, glob, os

for suite in ['libero_spatial', 'libero_object', 'libero_10', 'libero_goal', 'libero_90']:
    files = sorted(glob.glob(f'/root/autodl-tmp/libero_data/{suite}/*.hdf5'))
    print(f'\\n=== {suite}: {len(files)} files ===')
    if files:
        f0 = h5py.File(files[0], 'r')
        print(f'Top keys: {list(f0.keys())}')
        if 'data' in f0:
            demos = sorted(list(f0['data'].keys()))
            print(f'Demos: {len(demos)} (e.g. {demos[:3]})')
            if demos:
                d0 = f0['data'][demos[0]]
                print(f'Demo keys: {sorted(list(d0.keys()))}')
                for k in sorted(d0.keys()):
                    if hasattr(d0[k], 'shape'):
                        print(f'  {k}: shape={d0[k].shape}, dtype={d0[k].dtype}')
                    elif isinstance(d0[k], h5py.Group):
                        print(f'  {k}/ (group):')
                        for kk in sorted(d0[k].keys()):
                            if hasattr(d0[k][kk], 'shape'):
                                print(f'    {kk}: shape={d0[k][kk].shape}, dtype={d0[k][kk].dtype}')
        f0.close()
        # File size
        sz = os.path.getsize(files[0])
        total = sum(os.path.getsize(f) for f in files)
        print(f'Single file: {sz/1024/1024:.1f}MB, Total: {total/1024/1024/1024:.2f}GB')
